    def _purge_metrics_for_current_image(self):
        """
        Remove metrics artifacts for the CURRENT image only.
        Safe: does not touch other images.
        """
        import os, shutil

        base = self._image_base()   # canonical image key
        metrics_root = os.path.join(self.save_folder, "metrics")
        image_dir = os.path.join(metrics_root, base)

        if os.path.isdir(image_dir):
            try:
                shutil.rmtree(image_dir)
                print(f"[METRICS] 🧠¹ Purged metrics for image '{base}'")
            except Exception as e:
                print(f"[METRICS] ⚠ Failed to purge metrics for '{base}': {e}")
    
    def run_pipeline(self, multirun=False):
        import gc, json
        import numpy as np
        from PyQt5.QtWidgets import QMessageBox
        from time import time

        # ---- helpers ---------------------------------------------------------
        def _ensure_ann():
            # make sure base structure exists
            if not hasattr(self, "annotation") or not isinstance(self.annotation, dict):
                self.annotation = {}
            ann = self.annotation.setdefault("annotations", {})
            ann.setdefault("atomic_cracks", {})
            ann.setdefault("combined_cracks", {})
            # scrub stray non-numeric keys
            bad_keys = [k for k in ann["atomic_cracks"].keys() if not str(k).isdigit()]
            for bk in bad_keys:
                ann["atomic_cracks"].pop(bk, None)
            return ann

        def _next_crack_id_str():
            """
            Return the lowest non-negative id that is NOT used in saved atomic_cracks.
            This ignores any in-memory caches so deleted ids are reused.
            """
            ann = self.annotation.get("annotations", {})
            ac = ann.get("atomic_cracks", {})
            used = sorted(int(k) for k in ac.keys() if str(k).isdigit())
            nxt = 0
            for k in used:
                if k == nxt:
                    nxt += 1
                elif k > nxt:
                    break
            return str(nxt)

        # ---- start -----------------------------------------------------------
        gc.collect()
        print("✅ GPU memory freed from CuPy pool")
        print("Running midline pipeline (auto + manual)...")

        # reset scratch between runs so ids don't leak/inflate
        self.current_crack_id = None
        self.crack_tracks = {}        # in-memory geodesic paths per id (scratch only)

        ann = _ensure_ann()
        ac_store = ann["atomic_cracks"]

        # Keep crack bbox assignments coherent with current user boxes before grouping pairs.
        if hasattr(self, "_rematch_crack_bboxes_to_boxes"):
            try:
                self._rematch_crack_bboxes_to_boxes()
            except Exception as e:
                print(f"[bbox rematch] run_pipeline preflight failed: {e}")

        boxes = self.get_all_bounding_boxes()
        print(f"Loaded {len(boxes)} bounding boxes: {boxes}")
        if not boxes:
            QMessageBox.critical(None, "No Bounding Boxes",
                "Please draw at least one bounding box before running the pipeline.")
            return

        if not multirun:
            # Let the user pick points/connections/midlines
            self.endpoint_pairs = None
            self.user_connections = None
            self.user_points = None
            self.manual_endpoint_pairs = None
            self.all_selected_points = None  # reset before each run
            print("Calling select_end_points_manmidlines()...")
            self.select_end_points_manmidlines(metrics=False)

        # Merge auto + manual endpoint pairs (global, from annotator)
        all_pairs = []
        if getattr(self, "endpoint_pairs", None):
            print(f"Auto endpoint_pairs: {self.endpoint_pairs}")
            all_pairs.extend([(p, "auto") for p in self.endpoint_pairs])

        if getattr(self, "manual_endpoint_pairs", None):
            print(f"Manual endpoint_pairs: {self.manual_endpoint_pairs}")
            all_pairs.extend([(p, "manual") for p in self.manual_endpoint_pairs])

        if not all_pairs:
            QMessageBox.critical(
                None, "No Endpoint Pairs",
                "No endpoint pairs selected!\n\nPlease use 'Select Endpoints' and create at least one connection or manual midline before running the pipeline."
            )
            return

        # Group by bbox (so OS/cost is reused per box)
        box_to_pairs = {}
        dropped_pairs = []
        for (pair, src) in all_pairs:
            candidates = []
            for bbox in boxes:
                xmin, ymin, xmax, ymax = bbox
                p0, p1 = pair
                if (xmin <= p0[0] <= xmax and ymin <= p0[1] <= ymax and
                    xmin <= p1[0] <= xmax and ymin <= p1[1] <= ymax):
                    area = abs((xmax - xmin) * (ymax - ymin))
                    candidates.append((area, bbox))
            if candidates:
                _, chosen_bbox = min(candidates, key=lambda x: x[0])
                key = tuple(chosen_bbox)
                box_to_pairs.setdefault(key, []).append((pair, src))
            else:
                dropped_pairs.append((pair, src))

        if dropped_pairs:
            print("[PIPELINE] Skipping endpoint pairs with no corresponding bounding box:")
            for (p0, p1), src in dropped_pairs:
                print(f"  - source={src} pair={p0}->{p1}")

        if not box_to_pairs:
            QMessageBox.critical(
                None,
                "No Valid Endpoint Pairs",
                "All selected endpoint pairs are outside bounding boxes.\n\n"
                "Please draw/fix boxes so each crack pair is contained in at least one box.",
            )
            return

        errors = []

        # Make sure we don't blow away memory of previous masks
        if not hasattr(self, "mask"):
            self.mask = []

        for bbox_key, pairs in box_to_pairs.items():
            xmin, ymin, xmax, ymax = bbox_key
            print(f"\n=== Processing bbox {bbox_key} ===")
            print(f"Pairs in this box: {pairs}")

            try:
                # Precompute OS/cost once per box for auto pairs
                auto_pairs = [p for p, s in pairs if s == "auto"]
                if auto_pairs:
                    first_pair = auto_pairs[0]
                    print(f"Precomputing OS/cost for auto pair {first_pair}")
                    self.pts = [np.array(first_pair[0]), np.array(first_pair[1])]
                    self.end_points = self.pts
                    self.active_bbox = list(bbox_key)
                    self.update_image_crop()
                    if getattr(self, "skip_current_segment", False):
                        continue
                    print("os (once per box)")
                    self.update_os_cost()
                    #t0 = time(); self.update_os(); print(f"os time: {time()-t0:.2f}s")
                    #print("cost (once per box)")
                    #t0 = time(); self.update_cost(); print(f"cost time: {time()-t0:.2f}s")

                # Process each pair -> one atomic crack per pair
                for (p0, p1), src in pairs:
                    try:
                        self.active_bbox = list(bbox_key)
                        print(f"\n--- Processing pair {(p0, p1)} (source={src}) ---")

                        # Per-crack, pair-local endpoints for saving
                        pair_user_points = [tuple(p0), tuple(p1)]
                        pair_user_connections = [[0, 1]]  # exactly one connection per crack

                        if src in ("manual", "manual_poly"):
                            # For manual, we reuse the drawn polyline as midline (full-image coords)
                            manual_midlines_dict = getattr(self, "manual_midlines_tmp", {})
                            found_key = None

                            # Durable copy of selection points from earlier
                            all_points = getattr(self, "all_selected_points", None)
                            if all_points is None:
                                all_points = getattr(self, "user_points", [])

                            print("\n[DEBUG] --- Matching manual midline ---")
                            print(f"[DEBUG] manual_midlines_tmp keys at runtime: {list(manual_midlines_dict.keys())}")
                            print(f"[DEBUG] all_points at runtime: {all_points}")
                            print(f"[DEBUG] Trying to match p0={p0}  p1={p1}")

                            # manual_midlines_tmp keys are "i_j" from annotator indices; match geometrically     
                            for k, poly in manual_midlines_dict.items():
                                try:
                                    # handle both tuple keys (2,3) and string keys "2_3"
                                    if isinstance(k, tuple) and len(k) == 2:
                                        i1, i2 = map(int, k)
                                    elif isinstance(k, str) and "_" in k:
                                        i1, i2 = map(int, k.split("_"))
                                    else:
                                        print(f"[DEBUG] Unrecognized key format: {k!r}")
                                        continue

                                    c_i = tuple(all_points[i1])
                                    c_j = tuple(all_points[i2])
                                    print(f"[DEBUG] Checking key={k}, c_i={c_i}, c_j={c_j}")
                                    if (c_i, c_j) == (p0, p1) or (c_i, c_j) == (p1, p0):
                                        print(f"[DEBUG] Found match for key={k}")
                                        found_key = k
                                        break
                                except Exception as e:
                                    print(f"[DEBUG] Error parsing key={k}: {e}")

                            print(f"[MANUAL] Found key: {found_key}")
                            self.pts = [np.array(p0), np.array(p1)]
                            self.end_points = self.pts
                            self.update_image_crop()
                            if getattr(self, "skip_current_segment", False):
                                continue

                            if found_key:
                                # Convert full-image manual polyline to crop coords and set as self.track
                                poly = np.array(manual_midlines_dict[found_key], dtype=float)  # [[x,y],...]

                                """print("\n[DBG MANUAL POLYLINE] first 20 (FULL IMAGE COORDS):")
                                for i, (x, y) in enumerate(poly[:20]):
                                    print(f"  {i:02d}: ({x:.6f}, {y:.6f})")"""

                                cy = poly[:, 1] - ymin
                                cx = poly[:, 0] - xmin

                                """print("\n[DBG AFTER CROP OFFSET] first 20:")
                                for i in range(min(20, len(cx))):
                                    print(f"  {i:02d}: cx={cx[i]:.6f}, cy={cy[i]:.6f}")"""

                                self.track = np.vstack([cy, cx])

                                """print("\n[DBG TRACK ARRAY]")
                                print(f"  dtype: {self.track.dtype}")
                                print(f"  shape: {self.track.shape}")

                                print("[DBG TRACK first 20]:")
                                for i in range(min(20, self.track.shape[1])):
                                    print(f"  {i:02d}: (y={self.track[0, i]:.6f}, x={self.track[1, i]:.6f})")"""

                                # ---- endpoint bookkeeping (unchanged) ----
                                self.pts_crop = [
                                    np.array(self.pts[0]) - np.array([xmin, ymin]),
                                    np.array(self.pts[1]) - np.array([xmin, ymin])
                                ]

                                downsample = self.downsample_factor_box.value()
                                self.pts_crop_down = [p / downsample for p in self.pts_crop]
                            else:
                                msg = f"No manual polyline found for manual crack {p0}→{p1}"
                                print("ERROR:", msg)
                                errors.append(msg)
                                continue
                        else:
                            # Auto mode
                            self.pts = [np.array(p0), np.array(p1)]
                            self.end_points = self.pts
                            self.pts_crop = [np.array(pt) - np.array([xmin, ymin]) for pt in self.pts]
                            downsample = self.downsample_factor_box.value()
                            self.pts_crop_down = [p / downsample for p in self.pts_crop]
                            t0 = time(); self.midline_tracking(); print(f"    midline tracking time: {time()-t0:.2f}s")

                            # --- normalize track like generate_auto_variant_for_manual ---
                            if getattr(self, "track", None) is not None:
                                try:
                                    tr = np.asarray(self.track, float)
                                    if tr.shape[0] == 2:
                                        track_xy = tr.T
                                    else:
                                        track_xy = tr

                                    p0g = np.asarray(p0, float)
                                    p1g = np.asarray(p1, float)

                                    # reverse if needed (ensure start = p0)
                                    d_start_p0 = np.linalg.norm(track_xy[0] - p0g)
                                    d_start_p1 = np.linalg.norm(track_xy[0] - p1g)
                                    if d_start_p1 < d_start_p0:
                                        track_xy = track_xy[::-1]
                                        print(f"[PIPE ALIGN] reversed path so first sample anchors at p0 (d_start_p0={d_start_p0:.2f}, d_start_p1={d_start_p1:.2f})")
                                    else:
                                        print(f"[PIPE ALIGN] path already starts near p0 (d_start_p0={d_start_p0:.2f}, d_start_p1={d_start_p1:.2f})")

                                    # translate so first point == p0
                                    delta = p0g - track_xy[0]
                                    track_xy = track_xy + delta

                                    # convert to local coords (crop relative)
                                    xmin, ymin, xmax, ymax = bbox_key
                                    track_local = track_xy - np.array([xmin, ymin])
                                    track_local[:,0] = np.clip(track_local[:,0], 0, xmax - xmin - 1)
                                    track_local[:,1] = np.clip(track_local[:,1], 0, ymax - ymin - 1)
                                    self.track = track_local.T

                                    print(f"[PIPE ALIGN] normalized track: start Δ={np.linalg.norm(track_local[0] - (p0g - np.array([xmin, ymin]))):.2f}px")
                                except Exception as e:
                                    print(f"[PIPE ALIGN] ⚠ failed to normalize: {e}")

                        # Canonicalize spacing before geometry consumers (edge_mask/edge_tracking).
                        try:
                            if getattr(self, "track", None) is not None:
                                self.track, rs_info = canonicalize_track_for_edges(
                                    self.track,
                                    ds_target=1.0,
                                    min_spacing_auto=0.8,
                                    min_spacing_manual=0.3,
                                    preserve_endpoints=True,
                                    source=src,
                                )
                                med_txt = (
                                    f"{rs_info['med_before']:.3f}"
                                    if rs_info.get("med_before") is not None
                                    else "None"
                                )
                                print(
                                    f"[PIPE RESAMPLE {src}] med={med_txt}, "
                                    f"resampled={rs_info.get('did_resample')}, "
                                    f"len={rs_info.get('n_before')}→{rs_info.get('n_after')}"
                                )
                        except Exception as e:
                            print(f"[PIPE RESAMPLE] ⚠ canonicalization failed: {e}")
                        
                        # ======= Assign a brand-new crack ID for THIS pair (gap-free) =======
                        new_cid = _next_crack_id_str()
                        self.current_crack_id = int(new_cid)

                        def _dbg_track(label, track, n=20):
                            print(f"\n[DBG {label}]")
                            if track is None:
                                print("  track is None")
                                return
                            print(f"  dtype={track.dtype}, shape={track.shape}")
                            pts = track[:, :min(n, track.shape[1])]
                            for i in range(pts.shape[1]):
                                y, x = pts[:, i]
                                print(f"  {i:02d}: (y={y:.6f}, x={x:.6f})")

                        #_dbg_track("PRE edge_mask (track)", self.track)

                        # Geodesic edges & masks for this pair
                        self.current_source = src
                        start_time = time()
                        self.edge_mask()
                        edgemask_time = time()
                        #_dbg_track("EXIT edge_mask (track)", self.track)
                        print()
                        print(f"[TIME] Edge mask time: {edgemask_time - start_time}")
                        self.edge_tracking()
                        print()
                        print(f"[TIME] Edge tracking time: {time() - edgemask_time}")
                        #_dbg_track("EXIT edge_tracking (track)", self.track)

                        # Pair-local globals so save_current_segment writes them into that crack
                        self.user_points = pair_user_points
                        self.user_connections = pair_user_connections
                        
                        # === QUICK TEST TRIPWIRE ===
                        print(f"[TRIPWIRE] about to save crack with src={src}, p0={p0}, p1={p1}")
                        print(f"   track shape: {getattr(self, 'track', None).shape if hasattr(self, 'track') else None}")
                        print(f"   current_crack_id={self.current_crack_id}")
                        print(f"   manual_midlines_tmp keys: {list(getattr(self, 'manual_midlines_tmp', {}).keys())}")
                        print(f"   total atomic before save: {len(self.annotation['annotations']['atomic_cracks'])}")

                        # 🧠   For now, bail early to inspect what’s going on — no file write, no mutation
                        #return

                        # Save segment (midline + edges + mask + per-crack endpoints)
                        savetime = time()
                        self.save_current_segment()
                        print()
                        print(f"[TIME] Save current segment time: {time() - savetime}")

                        # Clear pair-local globals so next crack doesn't inherit them
                        self.user_points = None
                        self.user_connections = None

                    except Exception as e:
                        errors.append(f"Failed midline for {(p0, p1)}: {e}")
                        continue

            except Exception as e:
                errors.append(f"Failed for bbox {bbox_key}: {e}")
                continue

        # Done with all boxes/pairs
        if errors:
            print("\n".join(errors))
        else:
            print("✔ All endpoint groups processed.")

        # Clear UI temp state (per-run scratch)
        self.endpoint_pairs = None
        self.manual_endpoint_pairs = None

        # Persist JSON
        #self.save_annotation()
            
        
        self.auto_combine_segments()

        # Debug print & refresh view
        self._debug_print_atomic_cracks("run_pipeline END")
        self.change_image()
            
    def batch_run_pipeline(self):
        """
        Runs the pipeline (full segment generation, clearing endpoints/connections) on EVERY image in the selected folder.
        """
        from PyQt5.QtWidgets import QMessageBox
        import os
        
        # Check existence and content
        if not hasattr(self, "image_names") or not self.image_names:
            QMessageBox.warning(self.MainWindow, "Batch Run", "No images loaded. Please select a folder with images first.")
            print("Batch run aborted: no images loaded.")
            return
        
        total = len(self.image_names)
        errors = []
        n_success = 0
        orig_n = self.n

        def _extract_pairs_from_annotation():
            """
            Build endpoint pairs + manual midlines from the currently loaded annotation.
            Returns: (endpoint_pairs, manual_endpoint_pairs, manual_midlines_tmp,
                      user_points, user_connections)
            """
            ann = (self.annotation or {}).get("annotations", {}) or {}
            atomic = ann.get("atomic_cracks", {}) or {}
            if not atomic:
                return [], [], {}, [], []

            points = []
            point_index = {}

            def _add_point(pt):
                try:
                    x = float(pt[0])
                    y = float(pt[1])
                except Exception:
                    return None
                key = (x, y)
                idx = point_index.get(key)
                if idx is None:
                    idx = len(points)
                    point_index[key] = idx
                    points.append([x, y])
                return idx

            auto_conn_idx = []
            manual_conn_idx = []
            manual_midlines = {}
            seen_auto = set()
            seen_manual = set()

            for crack in atomic.values():
                src = str(crack.get("source") or crack.get("src") or "").lower()
                up = crack.get("user_points") or []
                if len(up) >= 2:
                    p1, p2 = up[0], up[1]
                else:
                    ml = crack.get("midline") or []
                    if len(ml) >= 2:
                        p1, p2 = ml[0], ml[-1]
                    else:
                        continue

                i1 = _add_point(p1)
                i2 = _add_point(p2)
                if i1 is None or i2 is None or i1 == i2:
                    continue

                if src in ("manual", "manual_poly", "manual_midline"):
                    mid = crack.get("midline") or []
                    if len(mid) < 2:
                        continue
                    key = (i1, i2)
                    if key not in seen_manual and (i2, i1) not in seen_manual:
                        seen_manual.add(key)
                        seen_manual.add((i2, i1))
                        manual_conn_idx.append((i1, i2))
                    manual_midlines[key] = [(float(x), float(y)) for (x, y) in mid]
                else:
                    key = (i1, i2)
                    if key in seen_auto or (i2, i1) in seen_auto:
                        continue
                    seen_auto.add(key)
                    seen_auto.add((i2, i1))
                    auto_conn_idx.append((i1, i2))

            endpoint_pairs = [(points[i1], points[i2]) for (i1, i2) in auto_conn_idx]
            manual_endpoint_pairs = [(points[i1], points[i2]) for (i1, i2) in manual_conn_idx]
            return endpoint_pairs, manual_endpoint_pairs, manual_midlines, points, auto_conn_idx

        for idx, fname in enumerate(self.image_names):
            try:
                base_name = os.path.splitext(os.path.basename(fname))[0]
                ann_path = os.path.join(self.save_folder, f"{base_name}.json")
                if not os.path.exists(ann_path):
                    print(f"  [SKIP] No annotation JSON for {base_name}.")
                    continue

                self.n = idx
                self.change_image()

                endpoint_pairs, manual_endpoint_pairs, manual_midlines_tmp, pts, conns = (
                    _extract_pairs_from_annotation()
                )

                # Only run if endpoints/connections are present
                if endpoint_pairs or manual_endpoint_pairs:
                    self.user_points = pts
                    self.user_connections = [list(c) for c in conns]
                    self.endpoint_pairs = endpoint_pairs
                    self.manual_endpoint_pairs = manual_endpoint_pairs
                    self.manual_midlines_tmp = manual_midlines_tmp
                    self.all_selected_points = list(pts)

                    print(f"\n======= Processing image {idx+1}/{total}: {fname} =======")
                    self.run_pipeline(multirun=True)  # Will clear endpoints on success
                    n_success += 1
                    #return
                else:
                    print(f"  [SKIP] No endpoints/connections for this image.")
            except Exception as e:
                errors.append(f"Image {fname}: {e}")

        self.n = orig_n
        self.change_image()
        summary = f"Batch pipeline run complete.\nSuccessful: {n_success}/{total}\n"
        if errors:
            summary += f"\nErrors:\n" + "\n".join(errors)
        print(summary)
        QMessageBox.information(self.MainWindow, "Batch pipeline finished", summary)
  
