    def export_gt_supervision_for_current_image(self):
        """
        One-click GT export:
        - Loads main annotation x.json (no snapshots)
        - Takes ONLY manual atomics
        - Groups atomics using pure GT logic (gt_groups_from_midlines_and_gtmask)
        - Calls export_gt_supervision_for_image(...) with GT mask
        """

        import os, json
        import numpy as np
        import cv2

        from helpers.supervision import (
            export_gt_supervision_for_image as _export_gt_sup,
        )
        from combiner import gt_groups_from_midlines_and_gtmask

        base_name = self._image_base()

        if getattr(self, "original_image", None) is None:
            print("[GT_SUP] no image loaded.")
            return

        if getattr(self, "current_mask", None) is None:
            print("[GT_SUP] no GT mask loaded.")
            return

        H, W = self.original_image.shape[:2]
        gt_mask = (self.current_mask > 0).astype(np.uint8)

        # -------------------------------
        # Load the main annotation JSON
        # -------------------------------
        ann_path = getattr(self, "ann_name", None)
        if not ann_path or not os.path.exists(ann_path):
            print(f"[GT_SUP] no annotation JSON for {base_name}")
            return

        def _bbox_snapshot_from_atomic(atomic_map):
            out = {}
            for _cid, _cr in (atomic_map or {}).items():
                if not isinstance(_cr, dict):
                    continue
                bb = _cr.get("mask_bbox", [])
                if isinstance(bb, (list, tuple)):
                    out[str(_cid)] = tuple(bb)
                else:
                    out[str(_cid)] = tuple()
            return out

        def _check_bbox_mutation(stage_name, atomic_map, ref_snapshot):
            mutated = []
            for _cid, _cr in (atomic_map or {}).items():
                if not isinstance(_cr, dict):
                    continue
                curr = tuple((_cr.get("mask_bbox", []) or []))
                prev = tuple(ref_snapshot.get(str(_cid), tuple()))
                if curr != prev:
                    mutated.append((str(_cid), prev, curr))
            if mutated:
                print(f"\n[ERROR] BBOX MUTATION DETECTED @ {stage_name}")
                for _cid, _prev, _curr in mutated:
                    print(f"  atomic {_cid}: {_prev} -> {_curr}")
            else:
                print(f"[CHECK] No bbox mutation @ {stage_name}")

        # Optional one-shot bbox repair called from GT supervision export.
        DEBUG_CALL_BBOX_REPAIR_IN_GT_SUP = True
        repaired_ann_json = None
        if DEBUG_CALL_BBOX_REPAIR_IN_GT_SUP:
            try:
                from pathlib import Path
                from tools.repair_atomic_bboxes import repair_bboxes as _repair_atomic_bboxes

                gt_sup_root = os.path.join(self.save_folder, "supervision", base_name)
                gt_sup_analysis = os.path.join(gt_sup_root, "analysis")
                os.makedirs(gt_sup_analysis, exist_ok=True)

                image_path = None
                try:
                    if hasattr(self, "image_names") and isinstance(getattr(self, "image_names", None), list):
                        image_path = self.image_names[self.n]
                except Exception:
                    image_path = None

                before_png = os.path.join(gt_sup_analysis, "bbox_repair_before.png")
                after_png = os.path.join(gt_sup_analysis, "bbox_repair_after.png")

                repaired_count, repaired_data = _repair_atomic_bboxes(
                    json_path=Path(ann_path),
                    contain_thresh=0.8,
                    weak_thresh=0.3,
                    image_path=(Path(image_path) if image_path else None),
                    before_png=Path(before_png),
                    after_png=Path(after_png),
                    return_data=True,
                )
                print(
                    f"[GT_SUP] bbox repair executed from export_gt_supervision_for_current_image "
                    f"(changed={int(repaired_count)})"
                )

                # Commit repaired state into live in-memory annotation (no heavy change_image()).
                if isinstance(repaired_data, dict):
                    repaired_ann_json = repaired_data
                    self.annotation = repaired_data
                    ann_root_live = self.annotation.setdefault("annotations", {})
                    self.combined_cracks = ann_root_live.get("combined_cracks", {}) or {}
                    try:
                        # Refresh light-weight snapshot structures from repaired authoring state.
                        self._sync_metrics_snapshot_from_authoring(
                            refresh_combine=False,
                            persist=False,
                        )
                    except Exception as _se:
                        print(f"[GT_SUP] snapshot refresh after bbox repair skipped: {_se}")
            except Exception as _e:
                print(f"[GT_SUP] bbox repair skipped/fail: {_e}")

        if isinstance(repaired_ann_json, dict):
            ann_json = repaired_ann_json
        else:
            with open(ann_path, "r", encoding="utf-8") as f:
                ann_json = json.load(f)

        authoring_atomic = (
            ann_json.get("annotations", {}) or {}
        ).get("atomic_cracks", {}) or {}

        # -----------------------------------------
        # Filter manual atomics ONLY (no snapshots)
        # -----------------------------------------
        def _is_manual(cr):
            src = (cr.get("source") or "").lower()
            return src in ("manual", "manual_poly", "manual_midline")

        atomic = {
            str(cid): cr
            for cid, cr in authoring_atomic.items()
            if _is_manual(cr)
        }

        try:
            atomic_debug_list = []
            for _cid, _cr in atomic.items():
                if not isinstance(_cr, dict):
                    continue
                atomic_debug_list.append({
                    "id": str(_cid),
                    "mask_bbox": _cr.get("mask_bbox"),
                    "midline": _cr.get("midline", []),
                })
            raw_dbg_png = os.path.join(self.save_folder, f"{base_name}_raw_json_atomics_debug.png")
            debug_plot_all_atomics(
                self.original_image,
                atomic_debug_list,
                title=f"RAW JSON DEBUG - {base_name}",
                out_png=raw_dbg_png,
                show=False,
            )
        except Exception as _e:
            print(f"[DEBUG ATOMICS] failed to render raw json view: {_e}")

        print(f"[GT_SUP] using {len(atomic)} manual atomics for {base_name}")

        if not atomic:
            print("[GT_SUP] no manual atomics, aborting.")
            return

        bbox_snapshot = _bbox_snapshot_from_atomic(atomic)
        _check_bbox_mutation("post-repair", atomic, bbox_snapshot)

        # -----------------------------------------
        # GT grouping (midlines + GT mask + endpoints)
        # -----------------------------------------
        combined_groups = gt_groups_from_midlines_and_gtmask(
            atomic=atomic,
            gt_mask=gt_mask,
            H=H,
            W=W,
        )
        _check_bbox_mutation("after-midline", atomic, bbox_snapshot)

        print(f"[GT_SUP] GT grouping produced {len(combined_groups)} combined groups.")

        # -----------------------------------------
        # Export manual GT supervision (atomic+combined)
        # -----------------------------------------
        _check_bbox_mutation("before-export", atomic, bbox_snapshot)
        # Temporarily set supervision debug target to current image.
        try:
            import helpers.supervision as _sup_mod
            _sup_mod.DEBUG_TARGET = str(base_name)
        except Exception:
            pass
        _export_gt_sup(
            base_name=base_name,
            save_root=self.save_folder,
            original_image=self.original_image,
            H=H,
            W=W,
            atomic=atomic,
            combined_groups=combined_groups,
            gt_mask=gt_mask,
            depth_full=getattr(self, "current_depth", None),
        )

        print(f"[EXPORT] GT supervision -> {len(atomic)} cracks ({base_name})")
     
    def run_et_metrics_current_image_quick(
        self, tau_px=3.0, crack_id=None, display=True, do_param_sweep=True,
        *, best_method_key=None, reexport=True, run_atomic_width_eval: bool = False,
    ):
        """
        Single-image DT/BEST/ET runner using the shared batch-compatible path.
        """
        import time

        if not getattr(self, "name", None):
            print("[metrics] no image loaded")
            return

        t0 = time.perf_counter()
        idx = int(getattr(self, "n", 0))
        edge_params = {"window_half_size": 45, "mu": 0.0, "l": 5, "p": 14, "seg_mode": "new"}

        res = self._run_metrics_for_image_idx(
            idx,
            edge_params=edge_params,
            export_supervision=bool(reexport),
            display=bool(display),
            best_method_key=best_method_key,
            edge_parallel_workers=None,
            run_atomic_width_eval=bool(run_atomic_width_eval),
        )
        print(f"[SMOKE] result={res}")
        try:
            tb = res.get("timing_breakdown", {}) if isinstance(res, dict) else {}
            if isinstance(tb, dict) and tb:
                print("[SMOKE TIMING] major groups (s):")
                for k in ("snapshot_sync_s", "edge_tracking_s", "metrics_total_s"):
                    if k in tb:
                        try:
                            print(f"  - {k}: {float(tb[k]):.3f}")
                        except Exception:
                            print(f"  - {k}: {tb[k]}")
                gt_sup = tb.get("gt_supervision", {})
                if isinstance(gt_sup, dict) and gt_sup:
                    print("[SMOKE TIMING] gt_supervision:")
                    for k, v in gt_sup.items():
                        try:
                            print(f"  - {k}: {float(v):.3f}")
                        except Exception:
                            print(f"  - {k}: {v}")
                core = tb.get("width_mask_core_by_supervision_s", {})
                if isinstance(core, dict) and core:
                    print("[SMOKE TIMING] core by supervision:")
                    for sup, sec in sorted(core.items(), key=lambda kv: str(kv[0])):
                        try:
                            print(f"  - {sup}: {float(sec):.3f}")
                        except Exception:
                            print(f"  - {sup}: {sec}")
                drv = tb.get("width_driver_step_s", {})
                if isinstance(drv, dict) and drv:
                    print("[SMOKE TIMING] width driver step totals:")
                    for step, sec in sorted(drv.items(), key=lambda kv: str(kv[0])):
                        try:
                            print(f"  - {step}: {float(sec):.3f}")
                        except Exception:
                            print(f"  - {step}: {sec}")
                try:
                    mtotal = float(tb.get("metrics_total_s", 0.0))
                    rows = tb.get("width_driver_rows", [])
                    if isinstance(rows, list) and rows:
                        known = float(
                            sum(
                                float(r.get("seconds", 0.0))
                                for r in rows
                                if str(r.get("step", "")) not in ("compare_widths_for_aligned_cracks_s",)
                            )
                        )
                    else:
                        known = float(sum(float(v) for v in (drv or {}).values()))
                    metrics_unaccounted = float(mtotal - known)
                    print(f"[SMOKE TIMING] metrics_unaccounted_s ~= {max(0.0, metrics_unaccounted):.3f}")
                except Exception:
                    pass
        except Exception as _tim_e:
            print(f"[SMOKE TIMING] parse failed: {_tim_e}")
        print(f"[SMOKE] elapsed={time.perf_counter() - t0:.2f}s")

